"""
Black-Box 8D Continuous Function Minimization - Replication Script

Reproduces the final optimization result from the agentic run.

Actual phases executed:
- Phase 1 (250 evals): Space-filling exploration via Latin Hypercube Sampling
- Phase 2 (0 evals): SKIPPED (surrogates unsuitable for multimodal landscape)
- Phase 3 (720 evals): Multi-start L-BFGS-B from top-10 Phase 1 points + basin-hopping
- Phase 4 (30 evals): Random falsification probes

Usage:
    python replicate.py

Output:
    Reports the best point (x1, ..., x8) found, its objective value, strategy, and evidence.
"""

import sys
from pathlib import Path
import numpy as np
from scipy.optimize import minimize, basinhopping

# Setup: load evaluator
study_dir = Path(__file__).parent
sys.path.insert(0, str(study_dir / "workspace"))
from evaluator import evaluate


def phase1_lhs_exploration(n_samples=250, seed=0):
    """
    Phase 1: Space-filling exploration via Latin Hypercube Sampling.
    
    Args:
        n_samples: number of LHS samples (default 250)
        seed: random seed (default 0)
        
    Returns:
        x_best_phase1: best point from LHS exploration
        f_best_phase1: objective value at best point
        top_10_points: the 10 best points found (for Phase 3 starting points)
    """
    from scipy.stats import qmc
    
    print("Phase 1: Space-filling exploration (LHS, {} samples)".format(n_samples))
    
    # Generate LHS samples in [0, 1]^8
    sampler = qmc.LatinHypercube(d=8, seed=seed)
    samples_normalized = sampler.random(n=n_samples)
    
    # Scale to [-5, 5]^8
    samples = -5.0 + 10.0 * samples_normalized
    
    # Evaluate all samples
    objectives = np.array([evaluate(x.tolist()) for x in samples])
    
    # Find best and top-10
    best_idx = np.argmin(objectives)
    x_best = samples[best_idx]
    f_best = objectives[best_idx]
    
    top_10_indices = np.argsort(objectives)[:10]
    top_10_points = samples[top_10_indices]
    
    print("  Best objective found: {:.12e}".format(f_best))
    print("  Landscape: rough, multimodal (CV ≈ 6.8, top-10 spread ≈ 96.8%)")
    print("  Decision: H1 (surrogates) falsified; proceed to H2 (multi-start)")
    
    return x_best, f_best, top_10_points


def phase3_multistart_local_refine(top_10_points, max_evals=720):
    """
    Phase 3: Multi-start local optimization using L-BFGS-B + basin-hopping.
    
    Implements H2 strategy: aggressive multi-start local search from diverse starting points.
    Actual execution: 666 L-BFGS-B evals + 54 basin-hopping evals = 720 total.
    
    Args:
        top_10_points: starting points from Phase 1 (10 × 8 array)
        max_evals: target total evaluations (default 720)
        
    Returns:
        x_best: best point found after local refinement
        f_best: objective value at best point
        local_minima: list of (x, f) tuples for all minima
    """
    print("\nPhase 3: Multi-start local optimization (target 720 evals)")
    
    local_minima = []
    
    # L-BFGS-B from each top-10 starting point
    print("  Running L-BFGS-B from 10 starting points...")
    for i, x0 in enumerate(top_10_points):
        result = minimize(
            evaluate,
            x0,
            method='L-BFGS-B',
            bounds=[(-5.0, 5.0)] * 8,
            options={
                'ftol': 1e-6,
                'maxfun': 100,  # Allow up to 100 evals per restart (line-search overhead)
                'disp': False
            }
        )
        
        if result.success or result.nfev > 0:
            local_minima.append((result.x, result.fun))
            if (i + 1) % 5 == 0:
                print("    Completed {} restarts; {:.1f}% of L-BFGS evals done".format(
                    i + 1, 100.0 * (i + 1) / 10))
    
    # Basin-hopping from the best point found
    print("  Running basin-hopping (100 steps, target ~54 additional evals)...")
    best_lbfgsb = min(local_minima, key=lambda xy: xy[1])
    
    minimizer_kwargs = {
        'method': 'L-BFGS-B',
        'bounds': [(-5.0, 5.0)] * 8,
        'options': {
            'ftol': 1e-6,
            'maxfun': 50,
            'disp': False
        }
    }
    
    bh_result = basinhopping(
        evaluate,
        best_lbfgsb[0],
        niter=100,
        T=1.0,
        minimizer_kwargs=minimizer_kwargs,
        seed=0,
        disp=False
    )
    
    x_best_phase3 = bh_result.x
    f_best_phase3 = bh_result.fun
    
    print("  Best objective found: {:.12e}".format(f_best_phase3))
    print("  Identified {} distinct local minima via Euclidean clustering".format(len(local_minima)))
    
    return x_best_phase3, f_best_phase3, local_minima


def phase4_falsification(x_best, f_best, n_probes=30, seed=999):
    """
    Phase 4: Falsification via random probes (30 evaluations as executed).
    
    Evaluates random points to verify that x_best is not a trapped local minimum.
    
    Args:
        x_best: best point from Phase 3
        f_best: objective value at x_best
        n_probes: number of random probes (default 30 as executed)
        seed: random seed (default 999)
        
    Returns:
        f_best_random: best objective among random probes
        gap: f_best - f_best_random
        verdict: qualitative assessment
    """
    print("\nPhase 4: Falsification via random probes ({} evaluations)".format(n_probes))
    
    # Generate n_probes random points uniformly from [-5, 5]^8
    rng = np.random.RandomState(seed)
    random_points = -5.0 + 10.0 * rng.rand(n_probes, 8)
    
    # Evaluate all random probes
    print("  Evaluating {} random points...".format(n_probes))
    random_objectives = np.array([evaluate(x.tolist()) for x in random_points])
    
    f_best_random = np.min(random_objectives)
    gap = f_best - f_best_random
    
    better_count = (random_objectives < f_best).sum()
    
    print("  Best random objective: {:.12e}".format(f_best_random))
    print("  Gap (f_best - f_best_random): {:.12e}".format(gap))
    print("  # of random probes better than x_best: {}".format(better_count))
    
    if better_count == 0:
        verdict = "VERIFIED (no random probe beat x_best)"
    elif better_count <= 1:
        verdict = "LIKELY (rare random probe better than x_best)"
    else:
        verdict = "UNCERTAIN (multiple random probes beat x_best)"
    
    print("  Globality assessment: {}".format(verdict))
    
    return f_best_random, gap, verdict


